tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(180deg,#ff0000,#0000ff)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-180/srgb from-[#ff0000] to-[#0000ff]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(180deg, #ff0000, #0000ff);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(180deg, #ff0000, #0000ff);
}

css-variables:
:root {
  --gradient-angle: 180deg;
  --gradient-color-1: #ff0000;
  --gradient-color-2: #0000ff;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1), var(--gradient-color-2));
}

/* Usage: background: var(--gradient); */

